#include <bits/stdc++.h>

using namespace std;

long long binomial[777][777];
int R, C;
long long totalCombinations;
long long minDifference = 1000000000000000000LL;
long long bestValue = -1;

void branch_and_bound(long long valueX, long long valueY, int idxX, int idxY) {
    long long diff = abs(valueX - valueY);
    if (minDifference <= 1 || diff - binomial[idxX][R] * binomial[idxY][R] >= minDifference)
        return;

    if (idxX == R - 1 && idxY == R - 1) {
        long long currentDiff = abs(valueX - valueY);
        if (currentDiff < minDifference) {
            minDifference = currentDiff;
            bestValue = valueX;
        }
        return;
    }

    if (idxX >= R) {
        long long diffX = binomial[idxX][R] - binomial[idxX - 1][R];
        long long sumY = binomial[idxY][R];
        branch_and_bound(valueX, valueY + diffX * sumY, idxX - 1, idxY);
    }

    if (idxY >= R) {
        long long sumX = binomial[idxX][R];
        long long diffY = binomial[idxY][R] - binomial[idxY - 1][R];
        branch_and_bound(valueX + sumX * diffY, valueY, idxX, idxY - 1);
    }
}

char seq[12345];
int prefixA[12345];
int prefixB[12345];
unordered_map<unsigned long long, long long> memo_table;

long long count_paths(long long leftScore, long long rightScore, int xIndex, int yIndex) {
    unsigned long long hash = ((unsigned long long)leftScore << 32) | ((unsigned long long)xIndex << 16) | yIndex;
    auto found = memo_table.find(hash);
    if (found != memo_table.end()) {
        return found->second;
    }

    long long &answer = memo_table[hash];
    long long diff = abs(leftScore - rightScore);
    if (diff - binomial[xIndex][R] * binomial[yIndex][R] > minDifference) {
        answer = 0;
        return answer;
    }

    if (xIndex < R || yIndex < R) {
        int stepCount = xIndex + yIndex;
        if (xIndex >= prefixA[stepCount] && yIndex >= prefixB[stepCount]) {
            int adjustedX = xIndex - prefixA[stepCount];
            int adjustedY = yIndex - prefixB[stepCount];
            answer = binomial[adjustedX + adjustedY][adjustedX];
            return answer;
        }
        answer = 0;
        return answer;
    }

    answer = 0;
    char current_char = seq[xIndex + yIndex - 1];
    if (current_char != 'B') {
        long long incrementX = binomial[xIndex][R] - binomial[xIndex - 1][R];
        long long sumY = binomial[yIndex][R];
        answer += count_paths(leftScore, rightScore + incrementX * sumY, xIndex - 1, yIndex);
    }
    if (current_char != 'A') {
        long long sumX = binomial[xIndex][R];
        long long incrementY = binomial[yIndex][R] - binomial[yIndex - 1][R];
        answer += count_paths(leftScore + sumX * incrementY, rightScore, xIndex, yIndex - 1);
    }
    return answer;
}

int main() {
    scanf("%d %d", &R, &C);
    for (int i = 0; i <= 2 * (R + C); ++i) {
        for (int j = 0; j <= 2 * (R + C); ++j) {
            if (j == 0) {
                binomial[i][j] = 1;
            } else if (i == 0) {
                binomial[i][j] = 0;
            } else {
                binomial[i][j] = binomial[i - 1][j] + binomial[i - 1][j - 1];
            }
        }
    }

    totalCombinations = binomial[R + C][R] * binomial[R + C][R];

    {
        long long valX = 0, valY = 0;
        int idxX = R + C, idxY = R + C;
        while (idxX >= R && idxY >= R) {
            if (valX > valY) {
                long long diffX = binomial[idxX][R] - binomial[idxX - 1][R];
                long long sumY = binomial[idxY][R];
                valY += diffX * sumY;
                idxX--;
            } else {
                long long sumX = binomial[idxX][R];
                long long diffY = binomial[idxY][R] - binomial[idxY - 1][R];
                valX += sumX * diffY;
                idxY--;
            }
        }
        minDifference = abs(valX - valY);
    }

    branch_and_bound(0, 0, R + C, R + C);
    scanf("%s", seq);
    prefixA[0] = prefixB[0] = 0;
    for (int i = 0; i < 2 * (R + C); ++i) {
        prefixA[i + 1] = prefixA[i] + (seq[i] == 'A');
        prefixB[i + 1] = prefixB[i] + (seq[i] == 'B');
    }

    long long finalCount = count_paths(0, 0, R + C, R + C);
    cout << finalCount << "\n";
    return 0;
}
